                        洞察xinxushu: {
                            trigger: {
                                player: 'phaseEnd',
                            },
                            forced: true,
                            audio: 'ext:有名扩展/audio:2',
                            filter(event, player) {
                                return player.countCards('he') >= 0;
                            },
                            content() {
                                'step 0';
                                player.chooseCardTarget({
                                    filterTarget(card, player, target) {
                                        //return player!=target;
                                        return true;
                                    },
                                    filterCard(card, player) {
                                        return lib.filter.cardDiscardable(card, player);
                                    },
                                    ai1(card) {
                                        if (get.tag(card, 'damage')) {
                                            return 20;
                                        }
                                        return 9 - get.value(card);
                                    },
                                    ai2(target) {
                                        var att = get.attitude(_status.event.player, target);
                                        if (att > 0) {
                                            if (target.isTurnedOver()) att += 3;
                                            if (target.hp == 1) att += 3;
                                        }
                                        return att;
                                    },
                                    position: 'he',
                                    prompt: get.prompt('洞察xinxushu'),
                                });
                                ('step 1');
                                if (result.targets?.length) {
                                    var target = result.targets[0];
                                    event.target = target;
                                    player.discard(result.cards);
                                    if (target.hp == target.maxHp && !target.isTurnedOver() && !target.isLinked()) {
                                        target.draw(5);
                                        event.finish();
                                    } else {
                                        var controls = ['摸牌'];
                                        if (target.hp < target.maxHp) {
                                            controls.push('回复体力');
                                        }
                                        if (target.isLinked() | target.isTurnedOver()) {
                                            controls.push('重置武将牌');
                                        }
                                        target.chooseControl(controls).ai = function () {
                                            if (target.isTurnedOver()) {
                                                return '重置武将牌';
                                            } else if (target.hp == 1 && target.maxHp > 2) {
                                                return '回复体力';
                                            } else if (target.hp == 2 && target.maxHp > 2 && target.countCards('h') > 1) {
                                                return '回复体力';
                                            } else {
                                                return '摸牌';
                                            }
                                        };
                                    }
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                event.control = result.control;
                                switch (event.control) {
                                    case '回复体力':
                                        event.target.recover(5);
                                        event.finish();
                                        break;
                                    case '摸牌':
                                        event.target.draw(5);
                                        event.finish();
                                        break;
                                    case '重置武将牌':
                                        if (event.target.isTurnedOver()) event.target.turnOver();
                                        break;
                                }
                                ('step 3');
                                if (event.control == '重置武将牌' && event.target.isLinked()) {
                                    event.target.link();
                                }
                            },
                            ai: {
                                expose: 0.2,
                                threaten: 1.4,
                            },
                        },
